import{_ as t,o,c as s,a0 as i}from"./chunks/framework.ChlVJx0I.js";const p=JSON.parse('{"title":"Skill tool extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/skill-tool.md","filePath":"extensions/skill-tool.md","lastUpdated":1792012601000}'),a={name:"extensions/skill-tool.md"};function l(r,e,n,h,d,c){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="skill-tool-extension" tabindex="-1">Skill tool extension <a class="header-anchor" href="#skill-tool-extension" aria-label="Permalink to &quot;Skill tool extension&quot;">​</a></h1><p>Lets a model load a skill <strong>by name</strong> - the missing half of how the shipped skills talk to each other.</p><p>The tracked skills reference each other by name: <code>grill-with-docs</code> says &quot;call the Skill tool twice, for &#39;grilling&#39; and &#39;domain-modeling&#39;&quot;, and most of the engineering and productivity suite does the same. The wording comes from the upstream&#39;s home environment, which has a Skill tool. pi does not: the model only learns where a skill lives from the skills section of the system prompt, so a name reference makes the model re-type the long install path by hand. It guesses - a sibling bucket, a mangled directory name - and the read dies with ENOENT (<a href="https://github.com/SeriousJul/pi-extensions/issues/143" target="_blank" rel="noreferrer">issue #143</a>).</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>The extension registers one tool, <code>skill</code>, with one parameter: the skill name.</li><li>The name resolves against the skill list <strong>pi itself loaded into the run</strong>, captured at each run&#39;s start. The tool can only ever point at a skill the model was told about; it never scans the filesystem.</li><li>A hit returns the skill&#39;s body with the frontmatter stripped, wrapped in the same block shape pi&#39;s <code>/skill:</code> expansion records: the tag with the name and the file location, and the line that names the base directory the skill&#39;s relative file references resolve against. pi normalizes a file&#39;s line endings before it parses the frontmatter, and the tool mirrors that, so a CRLF file returns the same body pi records.</li><li>A miss - a name pi does not know - comes back as an error carrying every loaded name, so the model corrects itself in one retry.</li><li>A file that vanished after the run started (a <code>/reload</code> race) reports the reload hint instead of a bare ENOENT.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>One pure core module (<code>extensions/skill-tool/core.ts</code>) owns the name lookup, the frontmatter strip, and the result text; the pi wiring (<code>index.ts</code>) registers the tool and captures the registry from <code>before_agent_start</code>. See <a href="/pi-extensions/adr/0035-the-skill-tool-loads-referenced-skills-by-name.html">ADR 0035</a>.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>The tool serves the skills of the run it was captured in: skills added or removed by a <code>/reload</code> appear from the next run on. If pi ever ships its own <code>skill</code> tool, the name collision is the one thing to revisit; until then the tool degrades to nothing on a pi that lacks the <code>systemPromptOptions.skills</code> field.</p>',9)])])}const k=t(a,[["render",l]]);export{p as __pageData,k as default};
